import React from "react";

function Products() {
  const products = [
    {
      id: 1,
      name: "Vitamin C Tablets",
      category: "Vitamins & Supplements",
      price: "Rs. 1,250",
    },
    {
      id: 2,
      name: "Daily Multivitamin",
      category: "Vitamins & Supplements",
      price: "Rs. 1,850",
    },
    {
      id: 3,
      name: "Gentle Face Cleanser",
      category: "Skincare",
      price: "Rs. 950",
    },
    {
      id: 4,
      name: "Digital Thermometer",
      category: "Healthcare",
      price: "Rs. 1,500",
    },
  ];

  return (
    <section
      style={{
        backgroundColor: "#0b0f0e",
        color: "white",
        padding: "80px 7%",
      }}
    >
      <div>
        <p style={{ color: "#20c997" }}>
          ✦ FEATURED PRODUCTS
        </p>

        <h2 style={{ fontSize: "40px" }}>
          Popular Healthcare Essentials
        </h2>

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(4, 1fr)",
            gap: "25px",
            marginTop: "40px",
          }}
        >
          {products.map((product) => (
            <div
              key={product.id}
              style={{
                backgroundColor: "#111816",
                border: "1px solid #263832",
                borderRadius: "15px",
                padding: "25px",
              }}
            >
              <div
                style={{
                  height: "180px",
                  backgroundColor: "#17231f",
                  borderRadius: "12px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: "50px",
                }}
              >
                💊
              </div>

              <p style={{ color: "#20c997", marginTop: "20px" }}>
                {product.category}
              </p>

              <h3>{product.name}</h3>

              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  marginTop: "20px",
                }}
              >
                <strong>{product.price}</strong>

                <button
                  style={{
                    backgroundColor: "#20c997",
                    border: "none",
                    padding: "10px 15px",
                    borderRadius: "8px",
                    cursor: "pointer",
                  }}
                >
                  + Cart
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

export default Products;
